const input = $json;
const text = String(input.message || input.last_message || '').toLowerCase();
let intent = 'unknown';
let urgency = 'low';
let human_required = false;
let recommended_action = 'wait';
let stage_action = 'keep';
let reason = 'No se detectó una señal suficiente para automatizar una acción.';
if (/contratar|avanzar|cómo seguimos|como seguimos|disponibilidad|pago|formas de pago|cuándo empezamos|cuando empezamos/.test(text)) {
  intent = 'purchase_signal'; urgency = 'high'; recommended_action = 'notify_human'; stage_action = 'advance'; human_required = true; reason = 'Se detectó una señal explícita de avance comercial.';
} else if (/caro|precio|presupuesto|descuento|rebaja|más barato|mas barato/.test(text)) {
  intent = 'objection'; urgency = 'medium'; recommended_action = 'notify_human'; human_required = true; reason = 'Se detectó una objeción o negociación de precio.';
} else if (/no puedo|ahora no|más adelante|mas adelante|otro momento|el mes que viene/.test(text)) {
  intent = 'not_now'; recommended_action = 'schedule'; stage_action = 'nurture'; reason = 'El prospecto indica que no es el momento adecuado.';
} else if (/no me interesa|no gracias|no quiero|dejá|deja de/.test(text)) {
  intent = 'negative'; recommended_action = 'close'; stage_action = 'close'; reason = 'El prospecto expresa una negativa.';
} else if (/cómo|como|qué|que|cuánto|cuanto|cuándo|cuando|pueden|podés|podes/.test(text)) {
  intent = 'question'; recommended_action = 'reply'; reason = 'El prospecto formula una pregunta que puede responderse con información autorizada.';
} else if (/sí|si|interesa|me interesa|perfecto|genial|bien/.test(text)) {
  intent = 'interested'; urgency = 'medium'; recommended_action = 'reply'; stage_action = 'advance'; reason = 'Se detectó interés positivo.';
}
return [{json:{...input, intent, urgency, human_required, recommended_action, stage_action, reason, confidence: intent === 'unknown' ? 0.35 : 0.82}}];
